// TST-051 context grid (14 §5): time budget {3, 6, 9, 12 h/week} × horizon {4 wk, 16 wk, 2 yr} ×
// distance {5K, 10K, HM, M, 50K, 100K} × profile {novice, masters 65+, age 16, postpartum, prior bone-stress,
// shift worker} = 432 cases. 14 says the grid "is generated by the property suite, not stored"
// (spec/fixtures-input/README.md), so the cases are built here, in the fixture format, from one adult
// base persona of spec/fixtures-input (tst050-p15). Every changed value is tagged `invented: TST-051 grid`.
import { addDays } from './dates.js';
import { clone, fixture } from './fixtures.js';
import type { Fixture } from './types.js';

const BUDGETS: [number, string[]][] = [
  [180, ['Tue', 'Thu', 'Sun']],
  [360, ['Tue', 'Thu', 'Sat', 'Sun']],
  [540, ['Mon', 'Tue', 'Thu', 'Sat', 'Sun']],
  [720, ['Mon', 'Tue', 'Wed', 'Thu', 'Sat', 'Sun']],
];
const HORIZONS = [4, 16, 104];
const DISTANCES = ['5K', '10K', 'HM', 'M', '50K', '100K'];
const PROFILES = ['novice', 'masters65', 'age16', 'postpartum', 'bone_stress_cleared', 'shift_worker'] as const;
export type GridProfile = (typeof PROFILES)[number];

const TAG = 'invented: TST-051 context grid case (14 §5); generated by oracle/src/grid.ts';

export function gridFixtures(): Fixture[] {
  const base = fixture('tst050-p15');
  const out: Fixture[] = [];
  for (const [minutes, days] of BUDGETS) for (const wk of HORIZONS) for (const dist of DISTANCES) for (const prof of PROFILES) {
    const f = clone(base);
    const i = f.input;
    f.fixture_id = `tst051-${minutes / 60}h-${wk}w-${dist.toLowerCase()}-${prof.replace(/_/g, '-')}`;
    f.persona = `TST-051 grid: ${minutes / 60} h/week, ${wk} weeks, ${dist} finish, ${prof}`;
    f.sources = ['14 §5 TST-051'];
    f.release = ['5K', '10K', 'HM'].includes(dist) ? 'MVP' : dist === 'M' ? 'R2' : 'R3';
    f.behaviour = { model: 'day0_only', replan: 'on_event', deviations: [], horizon_weeks: 0 };
    i.profile.available_days = days;
    i.profile.max_runs_per_week = days.length;
    i.profile.available_minutes_per_week = minutes;
    i.profile.long_run_day = 'Sun';
    i.goal.distance = dist;
    i.goal.goal_type = 'finish';
    i.goal.target_time_s = null;
    i.goal.race_date = addDays(i.today, 7 * (wk - 1) + 6);
    switch (prof) {
      case 'novice':
        i.profile.training_age_years = 0.15;
        break;
      case 'masters65':
        i.profile.birth_year = 1959; i.profile.birth_month = 4;
        break;
      case 'age16':
        i.profile.birth_year = 2010; i.profile.birth_month = 4;
        i.screening.guardian_attested_on = i.today;
        break;
      case 'postpartum':
        i.profile.sex = 'f';
        i.profile.special_status = [{ type: 'postpartum', start_date: addDays(i.today, -140), attested: true, has_given_birth: true }];
        break;
      case 'bone_stress_cleared':
        i.flags = [{ id: 'g1', kind: 'red_flag', subkind: 'bone_stress_highrisk', region: 'front of the shin', rule_id: 'SAF-003', raised_on: addDays(i.today, -120), status: 'cleared', cleared_on: addDays(i.today, -7), clearance_attested_on: addDays(i.today, -7) }];
        break;
      case 'shift_worker':
        i.profile.night_shift_dates = Array.from({ length: 16 }, (_, k) => addDays(i.today, 2 + 7 * k));
        break;
    }
    for (const k of ['profile.available_days', 'profile.max_runs_per_week', 'profile.available_minutes_per_week', 'goal.distance', 'goal.goal_type', 'goal.race_date'])
      f.provenance[k] = TAG;
    f.notes = 'Grid case: assert no gate bypassed, no cap broken (every invariant check), every infeasible case has ≥ 1 validated option, every special-population case carries a generic message (14 §5).';
    out.push(f);
  }
  return out;
}
